// Add an online entry without starting or writing either local game session.
(()=>{const header=document.querySelector('.header-meta');if(header&&!header.querySelector('[data-online-entry]')){const link=document.createElement('a');link.href=new URL('online.html',document.baseURI).href;link.dataset.onlineEntry='true';link.textContent='온라인 대국';header.prepend(link);}const setup=document.querySelector('#setupView');if(setup){const panel=document.createElement('section');panel.className='panel';const title=document.createElement('h3');title.textContent='친구와 온라인 대국';const description=document.createElement('p');description.textContent='실시간으로 함께 플레이하거나, 시간 날 때 한 턴씩 진행하세요.';const link=document.createElement('a');link.href=new URL('online.html',document.baseURI).href;link.textContent='실시간 · 턴제 방 만들기';panel.append(title,description,link);setup.append(panel);}})();
